 public MainForm(bool forCapture=false){capture=forCapture;Text="狂热运输3修改器 · 速智电玩 · v1.0.5";Size=new Size(1420,940);MinimumSize=new Size(1280,850);StartPosition=FormStartPosition.CenterScreen;Font=Theme.F();AutoScaleMode=AutoScaleMode.None;sidebar=new Panel{BackColor=Theme.Back};main=new Panel{BackColor=Theme.Back};Controls.Add(sidebar);Controls.Add(main);header=new Surface();main.Controls.Add(header);heading=LabelFor("常用功能 · 19",19,true);stats=LabelFor("等待连接《狂热运输3》",10);header.Controls.Add(heading);header.Controls.Add(stats);pages=new Panel{BackColor=Theme.Back};main.Controls.Add(pages);status=LabelFor("请进入可运行的地图，再连接修改器。",9);status.ForeColor=Theme.Muted;main.Controls.Add(status);
 string[] names={"常用功能","货物添加","世界管理","镜头书签","诊断"},ids={"features","cargo","world","camera","diagnostics"};for(int i=0;i<names.Length;i++){string id=ids[i];var b=new PillButton{Text=names[i],Width=104,Height=54};b.SetBounds(4,22+i*64,104,54);b.Click+=delegate{ShowPage(id);};sidebar.Controls.Add(b);navigation[id]=b;}connect=new PillButton{Text="自动识别",Primary=true};connect.Click+=delegate{ConnectGame();};sidebar.Controls.Add(connect);reset=new PillButton{Text="关闭全部功能"};reset.Click+=delegate{Request(new{op="reset"});};sidebar.Controls.Add(reset);online=LabelFor("● 游戏未连接",9);online.ForeColor=Theme.Muted;sidebar.Controls.Add(online);purchase=new PillButton{Text="立即购买",Primary=true};sidebar.Controls.Add(purchase);purchase.Click+=delegate{try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(BrandAssets.PurchaseUrl){UseShellExecute=true});}catch(Exception ex){status.Text="购买链接打开失败："+ex.Message;}};
 BuildFeatures();foreach(var kind in new[]{"cargo","world"}){var p=new CatalogPage(this,kind){Dock=DockStyle.Fill};catalogs.Add(p);AddPage(kind,p);}camera=new CameraPage(this){Dock=DockStyle.Fill};AddPage("camera",camera);var dp=new Panel{Dock=DockStyle.Fill};diagnosis=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=Theme.Input,ForeColor=Theme.Ink,Font=Theme.F(11),Dock=DockStyle.Fill};dp.Controls.Add(diagnosis);var export=new PillButton{Text="导出诊断",Primary=true,Dock=DockStyle.Bottom,Height=40};export.Click+=delegate{using(var dlg=new SaveFileDialog{Filter="JSON 诊断|*.json",FileName="狂热运输3-诊断.json"})if(dlg.ShowDialog(this)==DialogResult.OK)File.WriteAllText(dlg.FileName,StateJson,System.Text.Encoding.UTF8);};dp.Controls.Add(export);AddPage("diagnostics",dp);
 SizeChanged+=delegate{Arrange();};Arrange();ShowPage("features");timer.Tick+=delegate{Poll();};Shown+=delegate{RegisterKeys();timer.Start();ConnectGame();};FormClosing+=delegate{closing=true;timer.Stop();foreach(int id in hotkeys.Keys)Native.UnregisterHotKey(Handle,id);if(bridge!=null)bridge.Dispose();};}
 void AddPage(string id,Panel panel){panel.Visible=false;pages.Controls.Add(panel);pageViews[id]=panel;}
 void Arrange(){int h=ClientSize.Height-42;sidebar.SetBounds(4,36,116,h);main.SetBounds(130,48,Math.Max(200,ClientSize.Width-148),Math.Max(200,ClientSize.Height-58));header.SetBounds(0,0,main.Width,72);heading.SetBounds(24,17,365,42);stats.SetBounds(432,14,Math.Max(100,main.Width-454),48);pages.SetBounds(0,86,main.Width,Math.Max(130,main.Height-126));status.SetBounds(12,main.Height-29,main.Width-24,26);connect.SetBounds(4,Math.Min(354,h-159),104,36);reset.SetBounds(4,Math.Min(400,h-112),104,36);online.SetBounds(10,Math.Min(449,h-64),105,34);purchase.SetBounds(4,h-46,104,34);LayoutFeatures();}
 void BuildFeatures(){var fp=new Panel{Dock=DockStyle.Fill};groups=new FlowLayoutPanel{Dock=DockStyle.Top,Height=66,WrapContents=false,Padding=new Padding(3,0,0,0)};fp.Controls.Add(groups);featuresContent=new Panel();featureScroll=new ModernScrollPanel(featuresContent){Dock=DockStyle.Fill};fp.Controls.Add(featureScroll);fp.Controls.SetChildIndex(featureScroll,0);AddPage("features",fp);var specs=Data.Rows(Data.Json.DeserializeObject(Data.Resource("Features.json")));var gs=new[]{"全部"}.Concat(specs.Select(x=>Data.Str(x,"group")).Distinct());foreach(string g in gs){string value=g;var b=new PillButton{Text=g,Width=g=="全部"?76:g=="额外功能"?96:128,Height=32,Margin=new Padding(0,0,7,0)};groups.Controls.Add(b);b.Click+=delegate{SetGroup(value);};}foreach(var spec in specs){string g=Data.Str(spec,"group");Panel section;if(!sections.TryGetValue(g,out section)){section=new Panel{BackColor=Theme.Back,Tag=g};var label=LabelFor(g,11,true);label.SetBounds(8,10,500,36);section.Controls.Add(label);sections[g]=section;featuresContent.Controls.Add(section);}var c=new FeatureCard(spec);c.Requested+=FeatureRequested;c.KeyRequested+=BindKey;cards[c.Id]=c;section.Controls.Add(c);}featuresContent.SizeChanged+=delegate{LayoutFeatures();};SetGroup("全部");}
 void SetGroup(string value){group=value;foreach(PillButton b in groups.Controls)b.Primary=b.Text==group;foreach(var p in sections)p.Value.Visible=group=="全部"||group==p.Key;featureScroll.ScrollBar.Value=0;LayoutFeatures();}
 void LayoutFeatures(){if(featuresContent==null)return;int y=0,w=featuresContent.Width;foreach(var p in sections){if(group!="全部"&&group!=p.Key)continue;var cs=p.Value.Controls.OfType<FeatureCard>().ToList();p.Value.SetBounds(0,y,w,52+((cs.Count+1)/2)*104);int cw=(w-18)/2;for(int i=0;i<cs.Count;i++)cs[i].SetBounds((i%2)*(cw+16),52+(i/2)*104,cw,92);y+=p.Value.Height+20;}featureScroll.ContentHeight=y;}
 public void ShowPage(string id){if(id.StartsWith("features:")){SetGroup(id.Substring(9));id="features";}if(!pageViews.ContainsKey(id))id="features";page=id;foreach(var p in pageViews)p.Value.Visible=p.Key==id;foreach(var n in navigation)n.Value.Primary=n.Key==id;heading.Text=id=="features"?"常用功能 · "+cards.Count:id=="cargo"?"货物添加 · "+Data.Rows(Data.Get(State,"catalog")).Count(x=>Data.Str(x,"id")!="0"):id=="world"?"世界管理 · "+Data.Rows(Data.Get(State,"worlds")).Count:id=="camera"?"镜头书签":"连接诊断";if(id=="features")LayoutFeatures();}
 public void SelectFirst(){foreach(var c in catalogs)c.SelectFirst();}
 public void ConnectGame(){if(connecting||sending||closing)return;if(bridge!=null&&bridge.Ready){Request(new{op="refresh"});return;}connecting=true;Enable(connect,false);status.Text="正在连接游戏内存…";var candidate=new Bridge();Task.Run(delegate{try{candidate.Connect();if(closing){candidate.Dispose();return;}BeginInvoke((Action)delegate{if(bridge!=null)bridge.Dispose();bridge=candidate;connecting=false;Enable(connect,true);lastSnapshot="";status.Text="已连接游戏内存";Poll();});}catch(Exception e){candidate.Dispose();if(closing)return;BeginInvoke((Action)delegate{connecting=false;Enable(connect,true);status.Text=e.Message;});}});}
 public bool IsAvailable(string id){return CaptureReady&&Data.Bool(Data.Get(Data.Get(State,"capabilities"),id),"supported");}
 public string UnavailableReason(string id){return Data.Str(Data.Get(Data.Get(State,"capabilities"),id),"reason","当前接口尚未通过验证");}
 public void Request(object command){if(!CaptureReady){status.Text="请先连接游戏并进入可运行地图。";return;}var data=Data.Obj(Data.Json.DeserializeObject(Data.Json.Serialize(command)));string op=Data.Str(data,"op"),id=op=="set"?Data.Str(data,"id"):op;if(op!="reset"&&op!="refresh"&&!(op=="set"&&!Data.Bool(data,"enabled"))&&!IsAvailable(id)){status.Text=UnavailableReason(id);return;}requests.Enqueue(command);SendNext();}
 void SendNext(){if(sending||requests.Count==0||bridge==null)return;try{var c=requests.Dequeue();bridge.Send("return __SZTF3F6.dispatch("+Data.LuaObject(c)+")");sending=true;status.Text="正在提交操作…";}catch(Exception e){status.Text=e.Message;requests.Clear();}}
 void FeatureRequested(FeatureCard c){if(c.Kind=="action"||c.Kind=="number_action")Request(new{op=c.Id,value=c.Number.Value});else Request(new{op="set",id=c.Id,enabled=c.Toggle.Checked,value=c.Kind=="value"?c.Number.Value:1});}
 void Poll(){if(bridge==null||connecting||closing)return;try{bridge.Poll();if(sending&&!bridge.Pending){sending=false;try{if(bridge.LastResult!=1)throw new Exception(bridge.Response);var result=Data.Json.DeserializeObject(bridge.Response);status.Text=Data.Str(result,"message","操作完成");}catch(Exception e){status.Text=e.Message;requests.Clear();}SendNext();}if(lastSnapshot!=bridge.Snapshot){lastSnapshot=bridge.Snapshot;State=Data.Obj(Data.Json.DeserializeObject(lastSnapshot));State["connection"]=new{pid=bridge.Pid,processStartTicks=bridge.ProcessStartTicks,path=bridge.GamePath,gameVersion=bridge.GameVersion,steamBuild=bridge.GameBuild,pe=bridge.PeFingerprint,runtimeProtocol=Suzhi.TransportFever3.Protocol.RuntimeProtocol,compatibility="按唯一函数及 Lua 功能依赖验证"};UpdateState();}foreach(var c in catalogs)c.UpdateActions();camera.UpdateState();Enable(reset,CaptureReady&&!Busy);}catch(Exception e){status.Text=e.Message;bridge.Dispose();bridge=null;State=new Dictionary<string,object>();requests.Clear();sending=false;UpdateState();}}
 void UpdateState(){bool playing=CaptureReady;online.Text=playing?"● 游戏在线":"● 等待地图";online.ForeColor=playing?Theme.Green:Theme.Muted;stats.Text=playing?"结余 "+Data.Num(State,"balance").ToString("N0")+"   贷款 "+Data.Num(State,"loan").ToString("N0")+"   等级 "+Data.Num(State,"rank")+"\r\n"+Data.Str(State,"date")+"   模拟 "+Data.Num(State,"speed")+"x   经验 "+Data.Num(State,"experience").ToString("N0"):"请打开游戏，进入地图后连接。";var settings=Data.Obj(Data.Get(State,"settings"));var caps=Data.Obj(Data.Get(State,"capabilities"));foreach(var p in cards){object value;bool on=settings.TryGetValue(p.Key,out value);if(!sending&&requests.Count==0)p.Value.State(on,value);p.Value.Capability(Data.Get(caps,p.Key),playing);}foreach(var c in catalogs){c.UpdateRows(Data.Get(State,c.Kind=="cargo"?"catalog":"worlds"));c.UpdateStocks();}camera.UpdateState();Enable(reset,playing&&!Busy);ShowPage(page);int available=cards.Keys.Count(id=>Data.Bool(Data.Get(caps,id),"supported"));var d=Data.Get(State,"diagnostics");string txt="狂热运输3修改器 · v1.0.5\r\n\r\n"+(bridge==null?"尚未连接":bridge.IdentityText)+"\r\n运行方式：读取游戏内存，在游戏主线程提交命令\r\n\r\n常用功能："+available+" / "+cards.Count+" 项可用\r\n货物："+Data.Rows(Data.Get(State,"catalog")).Count(x=>Data.Str(x,"id")!="0")+"\r\n库存："+Data.Rows(Data.Get(State,"stocks")).Count+"\r\n城镇 / 产业："+Data.Rows(Data.Get(State,"worlds")).Count+"\r\n已提交命令："+Data.Num(d,"commands")+"\r\n待恢复参数："+Data.Num(d,"backups")+"\r\n\r\n状态："+Data.Str(State,"message")+"\r\n错误："+Data.Str(State,"error","无")+"\r\n\r\n关闭持续功能会恢复所备份的参数。\r\n修改器退出或断开超过 4 秒后，游戏下一次更新时自动恢复。\r\n资金、等级、经验、日期和目录操作属于一次性修改，\r\n关闭开关不会撤销；请用原存档恢复。";foreach(var item in caps){if(!Data.Bool(item.Value,"supported"))txt+="\r\n"+item.Key+"："+Data.Str(item.Value,"reason");}if(diagnosis.Text!=txt)diagnosis.Text=txt;}
 public void SavePrefs(){try{Prefs.Save();}catch(Exception e){status.Text="设置保存失败："+e.Message;}}
 public void Remember(string kind,string id){var l=Prefs.Set(kind,true);l.Remove(id);l.Insert(0,id);if(l.Count>30)l.RemoveRange(30,l.Count-30);SavePrefs();}
 void BindKey(FeatureCard c){int key;Prefs.keys.TryGetValue(c.Id,out key);using(var d=new KeyDialog(Data.Str(c.Spec,"name"),(Keys)key))if(d.ShowDialog(this)==DialogResult.OK){if(d.Selected==Keys.None)Prefs.keys.Remove(c.Id);else{foreach(var p in Prefs.keys)if(p.Key!=c.Id&&p.Value==(int)d.Selected){status.Text="该快捷键已绑定其他功能。";return;}Prefs.keys[c.Id]=(int)d.Selected;}SavePrefs();RegisterKeys();}}
 void RegisterKeys(){foreach(int id in hotkeys.Keys)Native.UnregisterHotKey(Handle,id);hotkeys.Clear();int next=100;foreach(var p in cards){int k;if(!Prefs.keys.TryGetValue(p.Key,out k)){p.Value.Hotkey.Text="设置快捷键";continue;}Keys key=(Keys)k;uint mods=0x4000;if((key&Keys.Control)!=0)mods|=2;if((key&Keys.Shift)!=0)mods|=4;if((key&Keys.Alt)!=0)mods|=1;if(Native.RegisterHotKey(Handle,next,mods,(uint)(key&Keys.KeyCode))){hotkeys[next++]=p.Key;p.Value.Hotkey.Text=new KeysConverter().ConvertToString(key);}else{p.Value.Hotkey.Text="绑定冲突";status.Text="快捷键被占用，请重新绑定。";}}}
 public async Task<bool> Regression(string path){var log=new List<object>();try{for(int i=0;i<600&&!CaptureReady;i++)await Task.Delay(50);if(!CaptureReady)throw new Exception("连接失败");if(cards.Count!=19||pageViews.ContainsKey("tasks")||navigation.Count!=5)throw new Exception("新版菜单包含多余条目");foreach(string category in sections.Keys){SetGroup(category);if(sections.Values.Count(x=>x.Visible)!=1||!sections[category].Visible)throw new Exception("分类显示异常："+category);}SetGroup("全部");log.Add(new{id="release_menu",pass=true,commonFeatures=cards.Count,navigationPages=navigation.Count});foreach(var id in new[]{"vehicle_speed","productivity"}){var original=cards[id];SetGroup("全部");original.Toggle.Checked=true;await WaitToggle(id,true);SetGroup(Data.Str(original.Spec,"group"));if(!object.ReferenceEquals(original,cards[id]))throw new Exception("分类重建了功能卡片");original.Toggle.Checked=false;await WaitToggle(id,false);original.Toggle.Checked=true;await WaitToggle(id,true);SetGroup("全部");original.Toggle.Checked=false;await WaitToggle(id,false);log.Add(new{id=id,pass=true,category=Data.Str(original.Spec,"group")});}ShowPage("cargo");SelectFirst();int changes=0;foreach(var b in pageViews["cargo"].Controls.Cast<Control>().SelectMany(Descendants).OfType<PillButton>())b.EnabledChanged+=delegate{changes++;};await Task.Delay(3500);if(changes!=0)throw new Exception("目录按钮在空闲刷新时反复改变状态："+changes);log.Add(new{id="idle_button_states",pass=true,enabledChanges=changes});File.WriteAllText(path,Data.Json.Serialize(log),System.Text.Encoding.UTF8);return true;}catch(Exception e){log.Add(new{error=e.ToString()});File.WriteAllText(path,Data.Json.Serialize(log),System.Text.Encoding.UTF8);return false;}}
 static IEnumerable<Control> Descendants(Control root){yield return root;foreach(Control c in root.Controls)foreach(var child in Descendants(c))yield return child;}
 async Task WaitToggle(string id,bool expected){for(int i=0;i<200;i++){if(!Busy&&Data.Obj(Data.Get(State,"settings")).ContainsKey(id)==expected)return;await Task.Delay(50);}throw new Exception("开关状态未同步："+id+" / "+expected);}
 protected override void WndProc(ref Message m){if(m.Msg==0x312){string id;if(hotkeys.TryGetValue(m.WParam.ToInt32(),out id)&&CaptureReady&&!Busy){var c=cards[id];if(c.Supported){if(c.Kind=="action"||c.Kind=="number_action")FeatureRequested(c);else c.Toggle.Checked=!c.Toggle.Checked;}}}base.WndProc(ref m);}
}
